"use client"

import type { Table } from "@tanstack/react-table"
import { RefreshCcw } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { DataTableViewOptions } from "./data-table-view-options"
import { AddProjectModal } from "./add-project-modal"

import type { Project } from "@/modules/projects/services/types/project-types"

interface DataTableToolbarProps<TData> {
  table: Table<TData>
  onCreateProject?: (project: Project) => void
}

export function DataTableToolbar<TData>({
  table,
  onCreateProject,
}: DataTableToolbarProps<TData>) {
  const isFiltered = table.getState().columnFilters.length > 0

  return (
    <div className="flex items-center justify-between">
      <div className="flex flex-1 items-center space-x-2">
        <Input
          placeholder="Search Project"
          value={(table.getColumn("title")?.getFilterValue() as string) ?? ""}
          onChange={(event) =>
            table.getColumn("title")?.setFilterValue(event.target.value)
          }
          className=" w-[200px] lg:w-[300px] cursor-text"
        />
        <Button
          variant="outline"
          onClick={() => table.resetColumnFilters()}
          className="px-3 cursor-pointer"
          disabled={!isFiltered}
        >
          <RefreshCcw className="h-4 w-4" />
          <span className="hidden lg:block">Reset Filters</span>
        </Button>
      </div>
      <div className="flex items-center space-x-2">
        <DataTableViewOptions table={table} />
        <AddProjectModal onAddProject={onCreateProject} />
      </div>
    </div>
  )
}
